def _route(minimum_duration, exact):
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bits.get(data["source"], 0)
        source, start = data["source"], data["start"]
        initial = (source, initial_mask, 0)
        dist = {initial: start}
        queue = [(start, source, initial_mask, 0)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full and
                    (used == data["coupons"] if exact else used <= data["coupons"])):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    time = depart + duration
                    if time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bits.get(next_node, 0)
                    nxt = (next_node, next_mask, next_used)
                    if time < dist.get(nxt, float("inf")):
                        dist[nxt] = time
                        heapq.heappush(queue, (time, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    mode = data["rounding"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", ("anonymous", pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    def rounded(num):
        return (num + 5000) // 10000 if mode == "half_up" else num // 10000

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _acyclic(chosen, features):
    graph = {}
    for name, version in chosen.items():
        row = next(row for row in _packages[name] if row["version"] == version)
        graph[name] = [d["name"] for d in row.get("deps", [])
                       if not d.get("feature") or d["feature"] in features]
    active, done = set(), set()

    def visit(name):
        if name in active:
            return False
        if name in done:
            return True
        active.add(name)
        if any(not visit(child) for child in graph.get(name, [])):
            return False
        active.remove(name)
        done.add(name)
        return True

    return all(visit(name) for name in graph)


def _resolver(data):
    global _packages
    _packages = data["packages"]
    names = sorted(_packages)
    features = set(data.get("features", []))
    constraints = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best = None

    def search(chosen, cons):
        nonlocal best_vector, best
        pending = sorted(name for name in cons if name not in chosen)
        if not pending:
            if _acyclic(chosen, features):
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector, best = vector, dict(chosen)
            return
        name = pending[0]
        ranges = cons[name]
        rows = [row for row in data["packages"].get(name, [])
                if all(low <= row["version"] <= high for low, high in ranges)
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_cons = {key: list(value) for key, value in cons.items()}
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                interval = (dep["min"], dep["max"])
                if child in next_chosen and not interval[0] <= next_chosen[child] <= interval[1]:
                    valid = False
                    break
                next_cons.setdefault(child, []).append(interval)
            if valid:
                search(next_chosen, next_cons)

    search({}, constraints)
    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    available = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in available}):
        return {"error": "impossible"}
    k = data["k"]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(available)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [available[i] for i in range(n) if mask >> i & 1]
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


